export const LEGACY_REDIRECT_MAP: Readonly<Record<string,string>> = { original 22 };
export const LEGACY_REDIRECT_ROUTE_ENTRIES = [...20];
export const MISSING_ORIGINAL_TARGETS = {...};

export const legacyCanonicalHref = (url: Url): string | undefined => {
  const pathname = normalize(url.pathname);
  const target = legacyTargetPath(pathname); // resolve map first then canonical (with cycle guard)
  if (target === undefined) return undefined;
  // preserve search & hash from original
  return target + search + hash;
}
```
But canonical target may already include query (Studio tab) and original may have search. Merge: if target has query, append `&` rest. Let's handle:
- `originalHref` path.
- For studio tab targets, canonical path includes `?tab=x`. Original query maybe `?foo=1`; combine `?tab=x&foo=1`, hash preserved.
- For non-studio targets, preserve original `search` and `hash`.

Canonical target resolution:
1. If pathname in LEGACY_REDIRECT_MAP → intermediate = map[pathname]; else intermediate = pathname.
2. If intermediate in CANONICAL_TARGETS → target = CANONICAL_TARGETS[intermediate]; else undefined.
This handles map entries that point to canonical original paths. For map-only entries `/app/local/models` → `/app/local/choose` → canonical target; `/app/router/config` → `/app/router/strategy` → missing (undefined). Good.
3. Original canonical path itself (e.g. `/app/models`) in CANONICAL_TARGETS → target direct.
4. `/app` → `/` (root). `/app/` normalize.
5. Should bare old paths without `/app` prefix? No. Only `/app/*`.

